export function rotateSession(s: Session): Session {
  // Rotation must restart the TTL window from the rotation time.
  const now = Date.now();
  return {
    ...s,
    issuedAt: now,
    expiresAt: now + SESSION_TTL,
    version: s.version + 1,
  };
}

